// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(address attacker, uint256 deposit) public {
        deposit = bound(deposit, 1, 1 ether);
        vm.assume(attacker != address(0));

        Attacker a = new Attacker(c);

        vm.deal(address(a), deposit);
        a.deposit{value: deposit}();

        uint256 prior = address(c).balance;

        a.attack();

        uint256 finalBalance = address(c).balance;
        assertTrue(finalBalance == prior - deposit);
    }
}

contract Attacker {
    ReentrancyDAO public target;
    bool public reentered;

    constructor(ReentrancyDAO _t) {
        target = _t;
        reentered = false;
    }

    function deposit() external payable {
        target.deposit{value: msg.value}();
    }

    function attack() external {
        target.withdrawAll();
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            target.withdrawAll();
        }
    }
}
